let viewedProfileId;const profileStyle=document.createElement('link');profileStyle.rel='stylesheet';profileStyle.href='profile.css';document.head.appendChild(profileStyle);const profileDialog=document.createElement('dialog');profileDialog.className='modal trust-modal';profileDialog.innerHTML='<button class="modal-close" type="button" id="closeTrustProfile">&times;</button><div id="trustProfileContent"></div>';document.body.appendChild(profileDialog);document.getElementById('closeTrustProfile').addEventListener('click',()=>profileDialog.close());async function loadTrustProfile(companyId,open=true){try{const p=await api(`/api/profiles/${companyId}`);viewedProfileId=companyId;const credential=x=>`<article class="credential-profile-card"><span class="connection-status ${new Date(x.expiresAt)>=new Date()?'accepted':''}">${escapeHtml(x.verificationStatus)}</span><h3>${escapeHtml(x.name)}</h3><p>${escapeHtml(x.type)}${x.issuer?` · ${escapeHtml(x.issuer)}`:''}</p><small>${x.credentialNumber?`Number: ${escapeHtml(x.credentialNumber)} · `:''}${x.expiresAt?`Expires ${escapeHtml(x.expiresAt)}`:'No expiration provided'}</small>${x.coverage?`<strong>${escapeHtml(x.coverage)}</strong>`:''}</article>`;const project=x=>`<article class="portfolio-card"><img src="${escapeHtml(x.photoUrl)}" alt="${escapeHtml(x.title)}"><div><span class="trade-pill">${escapeHtml(x.trade||'Completed work')}</span><h3>${escapeHtml(x.title)}</h3><p>${escapeHtml(x.description||'')}</p><small>${escapeHtml([x.city,x.state].filter(Boolean).join(', '))}${x.completedAt?` · ${escapeHtml(x.completedAt)}`:''}</small></div></article>`;profileDialog.querySelector('#trustProfileContent').innerHTML=`<div class="trust-profile-heading"><span class="kicker">Contractor due diligence</span><h2>${escapeHtml(p.company.name)}</h2><p>${escapeHtml(p.company.trades.join(' · ')||'Trades not listed')} · ${escapeHtml([p.company.city,p.company.state].filter(Boolean).join(', '))}</p></div><section><h3>Licenses, insurance, and credentials</h3><div class="credential-profile-grid">${p.credentials.length?p.credentials.map(credential).join(''):'<div class="list-empty">No credential information posted yet.</div>'}</div></section><section><h3>Recent completed work</h3><div class="portfolio-grid">${p.portfolio.length?p.portfolio.map(project).join(''):'<div class="list-empty">No completed-work photos posted yet.</div>'}</div></section><p class="due-diligence-note">Credential information is self-reported during the private alpha. Contractors should independently confirm licenses, insurance coverage, expiration dates, and applicability before hiring.</p>`;if(open)profileDialog.showModal();if(p.isOwner)renderProfileManager(p)}catch(error){showNotice(error.message,true)}}function renderProfileManager(p){const root=document.getElementById('profileDetails'),isSub=dashboard.company.capabilities.includes('subcontractor');root.innerHTML=isSub?`<p class="muted">Build contractor confidence with recent work and current credential information.</p><div class="profile-manage-grid"><form class="workspace-card trust-form" id="portfolioForm"><span class="kicker">Completed work</span><h3>Add a recent project</h3><label><span>Project title</span><input name="title" required></label><div class="form-row"><label><span>Trade</span><input name="trade"></label><label><span>Completion date</span><input name="completedAt" type="date"></label></div><div class="form-row"><label><span>City</span><input name="city"></label><label><span>State</span><input name="state" maxlength="2"></label></div><label><span>Photo image URL</span><input name="photoUrl" type="url" required placeholder="https://..."></label><label><span>Description</span><textarea name="description" rows="3"></textarea></label><button class="button button-orange" type="submit">Add completed work</button></form><form class="workspace-card trust-form" id="credentialForm"><span class="kicker">Due diligence</span><h3>Add license or insurance</h3><label><span>Type</span><select name="type" required><option value="license">License</option><option value="insurance">Insurance</option><option value="certification">Certification</option><option value="bond">Bond</option></select></label><label><span>Name</span><input name="name" required placeholder="General liability insurance"></label><div class="form-row"><label><span>Issuer</span><input name="issuer"></label><label><span>Number</span><input name="credentialNumber"></label></div><div class="form-row"><label><span>Issuing state</span><input name="state" maxlength="2"></label><label><span>Expires</span><input name="expiresAt" type="date"></label></div><label><span>Coverage or classification</span><input name="coverage" placeholder="$2M aggregate or license class"></label><label><span>Notes</span><textarea name="notes" rows="2"></textarea></label><button class="button button-dark" type="submit">Add credential information</button></form></div><button class="button button-outline" id="previewTrustProfile" type="button">Preview contractor view</button>`:'<p class="muted">Due-diligence profiles are available to subcontractor-capable companies.</p>';if(!isSub)return;document.getElementById('portfolioForm').addEventListener('submit',e=>submitTrust(e,'/api/profile/portfolio'));document.getElementById('credentialForm').addEventListener('submit',e=>submitTrust(e,'/api/profile/credentials'));document.getElementById('previewTrustProfile').addEventListener('click',()=>loadTrustProfile(dashboard.company.id))}async function submitTrust(event,path){event.preventDefault();try{await api(path,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget)))});event.currentTarget.reset();await loadTrustProfile(dashboard.company.id,false);showNotice('Trust profile updated.')}catch(error){showNotice(error.message,true)}}function addProfileButtons(){document.querySelectorAll('[data-message-bid],[data-connect],[data-request]').forEach(button=>{const id=button.dataset.messageBid||button.dataset.connect||button.dataset.request,container=button.closest('.directory-card,.bid-card');if(container&&!container.querySelector('[data-trust-profile]')){const x=document.createElement('button');x.type='button';x.className='text-link';x.dataset.trustProfile=id;x.textContent='View profile';container.querySelector('.connection-actions,.market-job-actions')?.appendChild(x)}});document.querySelectorAll('[data-trust-profile]').forEach(button=>button.onclick=()=>loadTrustProfile(button.dataset.trustProfile))}new MutationObserver(addProfileButtons).observe(document.body,{childList:true,subtree:true});document.querySelector('[data-view="profile"]').addEventListener('click',()=>loadTrustProfile(dashboard.company.id,false));const profileRefresh=refresh;refresh=async function(){await profileRefresh();if(dashboard.company.capabilities.includes('subcontractor'))await loadTrustProfile(dashboard.company.id,false);addProfileButtons()};
